CREATE TABLE customer_groups(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) NOT NULL UNIQUE,name VARCHAR(150) NOT NULL);
INSERT INTO customer_groups(code,name) VALUES('DEALER_1','Đại lý cấp 1'),('DEALER_2','Đại lý cấp 2'),('RETAIL','Khách lẻ');
CREATE TABLE price_versions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,group_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,valid_from DATE NOT NULL,valid_to DATE NOT NULL,parent_id BIGINT UNSIGNED NULL,revision BIGINT NOT NULL DEFAULT 1,FOREIGN KEY(group_id) REFERENCES customer_groups(id),FOREIGN KEY(parent_id) REFERENCES price_versions(id),CHECK(valid_to>=valid_from),INDEX(group_id,valid_from,valid_to));
CREATE TABLE price_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,version_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,selling_price DECIMAL(19,4) NOT NULL,floor_price DECIMAL(19,4) NOT NULL,UNIQUE(version_id,product_id),FOREIGN KEY(version_id) REFERENCES price_versions(id),FOREIGN KEY(product_id) REFERENCES products(id),CHECK(selling_price>=floor_price AND floor_price>=0));
CREATE TABLE price_order_references(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_reference VARCHAR(100) NOT NULL,price_item_id BIGINT UNSIGNED NOT NULL,version_id BIGINT UNSIGNED NOT NULL,selling_price DECIMAL(19,4) NOT NULL,floor_price DECIMAL(19,4) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(price_item_id) REFERENCES price_items(id),FOREIGN KEY(version_id) REFERENCES price_versions(id));
